import{_ as s,a0 as n,w as r,s as l,ao as d,I as a,x as e,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"7-Zip 22.00 最終版現已推出 | LCTT x X-CMD","titleTemplate":false,"description":"7-Zip 22.00 最終版現已推出 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7-Zip 22.00 最終版現已推出 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7-Zip 22.00 最終版現已推出 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220621 The Final Version Of 7-Zip 22.00 Is Now Available","title":"7-Zip 22.00 最終版現已推出","tag":"202206","desc":""},"relativePath":"202206/20220621 The Final Version Of 7-Zip 22.00 Is Now Available.md","filePath":"[post].md"}'),m={name:"202206/20220621 The Final Version Of 7-Zip 22.00 Is Now Available.md"};function u(f,t,T,w,x,Z){const i=n("Link");return r(),l("div",null,[t[15]||(t[15]=d('<h1 id="_7-zip-22-00-最終版現已推出" tabindex="-1">7-Zip 22.00 最終版現已推出 <a class="header-anchor" href="#_7-zip-22-00-最終版現已推出" aria-label="Permalink to “7-Zip 22.00 最終版現已推出”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/27/110310hwrmxuwyqlor1olp.jpg" alt=""></p><p>7-Zip 是用於 Windows、Mac 和 Linux 的知名開源文件歸檔器。它的最新版本 22.00 現已推出。它是 2022 年的第一個穩定版本。上一個版本是 21.07，於 2021 年 12 月發佈。7-Zip 的用户可以從官方網站獲取該應用的最新版本，下載適用於 Windows 64 位、32 位和 ARM 版本。該應用仍然與過時的 Windows 版本兼容，例如 XP 和 Vista。它還支持所有官方支持的 Windows 版本，包括服務器版本。適用於 Linux 的 7-Zip 22.00 已經可以下載，但 Mac OS 版本還不可用。</p><p>7-Zip 22.00 包含一些增強了應用功能的新特性。這個歸檔器現在支持提取<ruby>蘋果文件系統<rt>Apple File System</rt></ruby>（APFS）鏡像。幾年前，蘋果公司在 Mac OS 10.13 和 iOS 中引入了蘋果文件系統。該文件系統在設計時就考慮到了閃存（Flash）和固態硬盤（SSD）存儲。</p><p>7-Zip 22.00 包括了對其 TAR 存檔支持的多項增強。使用選項 <code>-ttar -mm=pax</code> 或 <code>-ttar -mm=posix</code>，7-Zip 現在可以創建符合 POSIX 標準的 tar 格式的 TAR 檔案。此外，使用選項 <code>ttar -mm=pax -mtp=3 -mtc -mta</code>，7-Zip 可以在 tar/pax 存檔中存儲高精度的文件時間戳。</p><p>最後，Linux 用户可以在 TAR 歸檔文件中使用以下兩個新選項：</p><ul><li><code>snoi</code>：將所有者/組 ID 保存在存檔中，或將所有者/組 ID 從存檔複製到提取的文件中。</li><li><code>snon</code>：在存檔中保留所有者/組的名稱。</li></ul><p>適用於 Windows 的 7-Zip 22.00 添加了對 <code>-snz</code> 選項的支持，該選項用於傳播區識別符（LCTT 譯註：區標識符是微軟在 2013 年為 IE 設計的安全功能，它會標記那些用户自網絡上所下載的文件，並在用户準備打開時跳出警告）。</p><p>要提取文件，請使用標識符流。出於安全目的，Windows 使用了該流，它可用於確定文件是在本地創建的還是從互聯網下載的。</p><p>在“<ruby>添加到存檔<rt>add to archive</rt></ruby>”配置對話框中，7-Zip 22.00 包含一個新的選項窗口。它包括用於更改時間戳精度、更改其他與時間相關的配置選項，以及防止更改源文件的最後訪問時間等選項。</p><hr>',11)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),o(i,{href:"https://www.opensourceforu.com/2022/06/the-final-version-of-7-zip-22-00-is-now-available/"},{default:p(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/06/the-final-version-of-7-zip-22-00-is-now-available/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=e("作者：",-1)),o(i,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:p(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),o(i,{href:"https://github.com/lkxed"},{default:p(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),o(i,{href:"https://github.com/lkxed"},{default:p(()=>[...t[4]||(t[4]=[e("lkxed",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const v=s(m,[["render",u]]);export{h as __pageData,v as default};
